package com.bank.queue;

import java.math.BigDecimal;
import java.util.LinkedList;
import java.util.Queue;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class QueueDemo {

    private static final Logger log = Logger.getLogger(QueueDemo.class.getName());

    static {
        // Clean single-line log formatter for the bank demo.
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TransferQueueProcessor processor = new TransferQueueProcessor();

        // Three requests arrive in order. FIFO must preserve this order.
        processor.submitTransfer(new TransferRequest("SAV2001", "CUR3001", new BigDecimal("50000")));
        processor.submitTransfer(new TransferRequest("CUR3001", "SAV2001", new BigDecimal("12000")));
        processor.submitTransfer(new TransferRequest("SAV2001", "CUR3001", new BigDecimal("3000")));

        log.info(() -> "Pending requests in queue: " + processor.pendingCount());

        // Process every request in the exact order they arrived.
        while (!processor.isEmpty()) {
            processor.processNext();
        }

        log.info("All transfers processed in FIFO order.");
    }
}

// ─── Would be in model/TransferRequest.java in a real project ───
class TransferRequest {
    private final String fromAccount;
    private final String toAccount;
    private final BigDecimal amount;

    TransferRequest(String fromAccount, String toAccount, BigDecimal amount) {
        this.fromAccount = fromAccount;
        this.toAccount = toAccount;
        this.amount = amount;
    }

    String getFromAccount() { return fromAccount; }
    String getToAccount() { return toAccount; }
    BigDecimal getAmount() { return amount; }
}

// ─── Would be in service/TransferQueueProcessor.java in a real project ───
class TransferQueueProcessor {

    private static final Logger log = Logger.getLogger(TransferQueueProcessor.class.getName());

    // LinkedList implements the Queue interface. offer() adds at rear, poll() removes from front.
    private final Queue<TransferRequest> pendingTransfers = new LinkedList<>();

    // enqueue: add a new request at the BACK of the line.
    void submitTransfer(TransferRequest request) {
        pendingTransfers.offer(request);
        log.info(() -> "ENQUEUE at rear: " + request.getFromAccount()
                + " -> " + request.getToAccount() + " Rs." + request.getAmount());
    }

    // dequeue: remove and process the request at the FRONT of the line.
    void processNext() {
        TransferRequest request = pendingTransfers.poll(); // returns null if empty
        if (request == null) {
            log.warning("No pending transfer to process.");
            return;
        }
        log.info(() -> "DEQUEUE from front and PROCESS: " + request.getFromAccount()
                + " -> " + request.getToAccount() + " Rs." + request.getAmount());
    }

    boolean isEmpty() { return pendingTransfers.isEmpty(); }

    int pendingCount() { return pendingTransfers.size(); }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
